DECLARE j constant jsonb := $records$[{"id": "710b08ef-a3b0-513a-8b41-90ab16f014af", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "es", "slug": "arepas-de-choclo-con-queso", "public_path": "/arepas-de-choclo-con-queso", "source_url": null, "title": "Arepas de choclo con queso", "excerpt": "Arepas colombianas de maíz tierno, doradas en sartén y cubiertas de mozzarella. Cuatro unidades con masa espesa, reposo y cocción por tandas.", "summary": "Arepas colombianas de maíz tierno, doradas en sartén y cubiertas de mozzarella. Cuatro unidades con masa espesa, reposo y cocción por tandas.", "content_html": "<p>Arepas colombianas de maíz tierno, doradas en sartén y cubiertas de mozzarella. Cuatro unidades con masa espesa, reposo y cocción por tandas.</p>", "category": "Panes y masas", "category_slug": "panes-y-masas", "cuisine": "Colombiana", "difficulty": "Fácil", "course": "Panes y masas", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "granos de maíz dulce fresco, crudos", "group": "Masa"}, {"amount": "60", "unit": "g", "name": "harina de maíz precocida amarilla para arepas", "group": "Masa"}, {"amount": "40", "unit": "g", "name": "leche entera", "group": "Masa"}, {"amount": "20", "unit": "g", "name": "mantequilla sin sal: 10 g para la masa y 10 g para la sartén", "group": "Masa y cocción"}, {"amount": "12", "unit": "g", "name": "azúcar blanca", "group": "Masa"}, {"amount": "2", "unit": "g", "name": "sal fina", "group": "Masa"}, {"amount": "120", "unit": "g", "name": "mozzarella de leche entera, en láminas", "group": "Cobertura"}], "steps": [{"title": "Tritura el maíz", "content": "Retira los hilos y restos de tusa del maíz y pesa 500 g de granos comestibles. Tritúralos con los 40 g de leche, el azúcar y la sal en pulsos cortos, hasta obtener una pasta con pequeños trozos de maíz. No añadas agua ni la conviertas en un líquido fino. Funde 10 g de mantequilla y deja que se temple.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "Maíz dulce triturado con leche en un procesador"}, {"title": "Mezcla y deja reposar", "content": "Pasa el maíz a un cuenco. Incorpora los 60 g de harina de maíz precocida y los 10 g de mantequilla fundida. Mezcla y deja reposar 10 minutos. Debe quedar una masa espesa que caiga lentamente de la cuchara y pueda extenderse, no una masa firme para amasar. Si queda demasiado líquida, espera 5 minutos más; cualquier harina o líquido adicional cambiará la fórmula y la nutrición estimada.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "Masa espesa de maíz amarillo mezclada con una cuchara"}, {"title": "Forma y dora la primera cara", "content": "Calienta una sartén antiadherente amplia a fuego medio-bajo durante 3 minutos. Usa 5 g de la mantequilla restante para la primera tanda. Divide la masa en cuatro partes iguales; cocina dos por tanda. Extiende cada porción con una cuchara en un círculo de unos 12 cm y 1 cm de grosor. Cocina 5 minutos sin moverla, hasta que el borde se vea firme y la base esté dorada. Baja el fuego si se tuesta antes de que el borde se afirme.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "Dos arepas de maíz tierno cocinándose por la primera cara"}, {"title": "Voltea y funde el queso", "content": "Introduce una espátula ancha por debajo y da la vuelta con cuidado. Cocina la segunda cara 5 minutos. Reparte 30 g de mozzarella sobre cada arepa, tapa y calienta 1 minuto más, hasta que el queso se ablande. La masa del centro debe estar cuajada, sin pasta cruda; si aún está húmeda y cruda, prolonga la cocción a fuego bajo. Repite con la otra mitad de la masa y los últimos 5 g de mantequilla.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "Arepas doradas en la sartén con mozzarella fundiéndose encima"}, {"title": "Sirve calientes", "content": "Sirve una arepa con 30 g de queso por persona, sin doblarla. El tiempo orientativo suma 10 minutos de preparación, 10 de reposo y 25 de cocción para dos tandas; añade el tiempo extra que necesite tu sartén. Deja enfriar las sobras y refrigéralas antes de 2 horas, a 4 °C o menos. Consúmelas en 3 días y recaliéntalas hasta que estén bien calientes en el centro.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "Arepas de choclo doradas con una capa de mozzarella sobre un plato"}], "notes": "Propuesta editorial original pendiente de prueba de cocina. Contiene leche. Usa maíz dulce fresco crudo; si usas congelado, descongélalo y escúrrelo antes de pesar. El maíz en conserva y otras harinas requieren ajustar la humedad. Usa harina precocida para arepas, no polenta gruesa. La dulzura depende del maíz. Puedes usar queso campesino, pero su textura y valores nutricionales serán distintos. La estimación incluye los 20 g de mantequilla completos; los restos en la sartén no se han medido. No incluye acompañamientos.", "keywords": ["Arepas de choclo con queso"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "Una de 4 arepas con 30 g de queso", "method": "Suma de gramos comestibles × nutrientes USDA por 100 g, dividida entre 4. Incluye los 20 g de mantequilla completos; rendimiento cocinado y restos en la sartén no medidos.", "note": "Estimación, no análisis de laboratorio ni prueba de cocina. La harina de maíz amarilla genérica es un proxy nutricional para la harina precocida de arepas; las marcas varían. Incluye mantequilla y queso completos, sin acompañamientos."}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "Arepas de choclo con queso"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "Arepas de choclo con queso", "description": "Arepas colombianas de maíz tierno, doradas en sartén y cubiertas de mozzarella. Cuatro unidades con masa espesa, reposo y cocción por tandas.", "about": "Arepas colombianas de maíz tierno, doradas en sartén y cubiertas de mozzarella. Cuatro unidades con masa espesa, reposo y cocción por tandas.", "faq": [{"q": "¿Por qué se rompe al voltearla?", "a": "Puede faltar reposo o cocción de la primera cara. Espera a que el borde esté firme y usa una espátula ancha; no la voltees mientras la base siga pegada."}, {"q": "¿Puedo usar maíz congelado?", "a": "Sí, descongelado y bien escurrido, pesando 500 g. La humedad puede variar; deja reposar la mezcla y comprueba que sea espesa antes de cocinar."}, {"q": "¿Puedo sustituir la harina por polenta?", "a": "No como sustitución directa: la polenta gruesa no hidrata igual. Esta fórmula usa harina de maíz precocida para arepas."}], "image_alt": "Arepas de choclo con queso", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}, {"id": "6169a5a9-7345-501b-a62c-096225757eb6", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "de", "slug": "mais-arepas-mit-kaese", "public_path": "/de/mais-arepas-mit-kaese", "source_url": null, "title": "Mais-Arepas mit Käse", "excerpt": "Kolumbianische Arepas aus frischem Zuckermais, in der Pfanne gebraten und mit Mozzarella belegt. Vier Stück mit dickem Teig, Ruhezeit und zwei Bratdurchgängen.", "summary": "Kolumbianische Arepas aus frischem Zuckermais, in der Pfanne gebraten und mit Mozzarella belegt. Vier Stück mit dickem Teig, Ruhezeit und zwei Bratdurchgängen.", "content_html": "<p>Kolumbianische Arepas aus frischem Zuckermais, in der Pfanne gebraten und mit Mozzarella belegt. Vier Stück mit dickem Teig, Ruhezeit und zwei Bratdurchgängen.</p>", "category": "Brote und Teige", "category_slug": "panes-y-masas", "cuisine": "Kolumbianisch", "difficulty": "Einfach", "course": "Brote und Teige", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "frische rohe Zuckermaiskörner", "group": "Teig"}, {"amount": "60", "unit": "g", "name": "vorgekochtes gelbes Maismehl für Arepas", "group": "Teig"}, {"amount": "40", "unit": "g", "name": "Vollmilch", "group": "Teig"}, {"amount": "20", "unit": "g", "name": "ungesalzene Butter: 10 g für den Teig und 10 g für die Pfanne", "group": "Teig und Braten"}, {"amount": "12", "unit": "g", "name": "weißer Zucker", "group": "Teig"}, {"amount": "2", "unit": "g", "name": "feines Salz", "group": "Teig"}, {"amount": "120", "unit": "g", "name": "Mozzarella aus Vollmilch, in Scheiben", "group": "Belag"}], "steps": [{"title": "Mais zerkleinern", "content": "Maisfäden und Kolbenreste entfernen und 500 g essbare Körner abwiegen. Mit 40 g Milch, Zucker und Salz kurz pulsierend zu einer groben Paste mit kleinen Maisstückchen zerkleinern. Kein Wasser zugeben und nicht flüssig pürieren. 10 g Butter schmelzen und etwas abkühlen lassen.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "Frischer Zuckermais mit Milch im Zerkleinerer"}, {"title": "Mischen und ruhen lassen", "content": "Mais in eine Schüssel geben. 60 g vorgekochtes Maismehl und 10 g geschmolzene Butter einrühren. 10 Minuten ruhen lassen. Der dicke Teig soll langsam vom Löffel fallen und sich verstreichen lassen, nicht knetbar sein. Ist er zu flüssig, weitere 5 Minuten warten; zusätzliches Mehl oder Flüssigkeit verändert Rezeptur und geschätzte Nährwerte.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "Dicker gelber Maisteig auf einem Löffel"}, {"title": "Formen und erste Seite braten", "content": "Eine große beschichtete Pfanne 3 Minuten bei mittlerer bis niedriger Hitze vorwärmen. Für den ersten Durchgang 5 g der übrigen Butter verwenden. Den Teig in vier gleiche Portionen teilen und jeweils zwei braten. Jede Portion etwa 12 cm breit und 1 cm dick verstreichen. 5 Minuten ungestört braten, bis der Rand fest und die Unterseite goldbraun ist. Wird sie vorher dunkel, die Hitze reduzieren.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "Zwei Mais-Arepas braten auf der ersten Seite"}, {"title": "Wenden und Käse schmelzen", "content": "Einen breiten Pfannenwender unterschieben und vorsichtig wenden. Die zweite Seite 5 Minuten braten. Je 30 g Mozzarella daraufgeben, abdecken und 1 weitere Minute erwärmen. Der Teig muss innen gestockt sein, ohne rohe Paste; andernfalls bei niedriger Hitze länger garen. Mit dem restlichen Teig und den letzten 5 g Butter wiederholen.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "Goldbraune Arepas mit schmelzendem Mozzarella in der Pfanne"}, {"title": "Warm servieren", "content": "Pro Person eine nicht gefaltete Arepa mit 30 g Käse servieren. Die Richtzeit umfasst 10 Minuten Vorbereitung, 10 Minuten Ruhe und 25 Minuten Braten in zwei Durchgängen; je nach Pfanne länger garen. Reste abkühlen und innerhalb von 2 Stunden bei höchstens 4 °C kühlen. Innerhalb von 3 Tagen essen und vollständig heiß aufwärmen.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "Vier goldbraune Mais-Arepas mit Mozzarella auf einem Teller"}], "notes": "Eigenständiger Rezeptvorschlag, noch nicht in der Küche getestet. Enthält Milch. Frischen rohen Zuckermais verwenden; gefrorenen Mais vor dem Wiegen auftauen und abtropfen lassen. Dosenmais und andere Mehle erfordern eine angepasste Feuchtigkeit. Vorgekochtes Arepa-Mehl verwenden, keine grobe Polenta. Die Süße hängt vom Mais ab. Kolumbianischer Frischkäse ist möglich, verändert aber Textur und Nährwerte. Die Schätzung enthält alle 20 g Butter; Pfannenreste sind nicht gemessen. Ohne Beilagen.", "keywords": ["Mais-Arepas mit Käse"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "Eine von 4 Arepas mit 30 g Käse", "method": "Essbare Zutatengewichte × USDA-Nährwerte je 100 g summieren und durch 4 teilen. Alle 20 g Butter sind enthalten; Garertrag und Pfannenreste sind nicht gemessen.", "note": "Schätzung, keine Laboranalyse oder Küchenprüfung. Generisches gelbes Maismehl dient als Näherung für vorgekochtes Arepa-Mehl; Marken unterscheiden sich. Einschließlich Butter und Käse, ohne Beilagen."}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "Mais-Arepas mit Käse"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "Mais-Arepas mit Käse", "description": "Kolumbianische Arepas aus frischem Zuckermais, in der Pfanne gebraten und mit Mozzarella belegt. Vier Stück mit dickem Teig, Ruhezeit und zwei Bratdurchgängen.", "about": "Kolumbianische Arepas aus frischem Zuckermais, in der Pfanne gebraten und mit Mozzarella belegt. Vier Stück mit dickem Teig, Ruhezeit und zwei Bratdurchgängen.", "faq": [{"q": "Warum bricht die Arepa beim Wenden?", "a": "Möglicherweise fehlt Ruhezeit oder die erste Seite ist noch nicht gar. Einen festen Rand abwarten und einen breiten Wender benutzen; nicht wenden, solange die Unterseite festklebt."}, {"q": "Kann ich gefrorenen Mais verwenden?", "a": "Ja, auftauen, gut abtropfen lassen und 500 g abwiegen. Die Feuchtigkeit variiert; den Teig ruhen lassen und vor dem Braten auf dicke Konsistenz prüfen."}, {"q": "Kann ich Polenta statt Maismehl verwenden?", "a": "Nicht direkt: Grobe Polenta nimmt Wasser anders auf. Diese Rezeptur verwendet vorgekochtes Maismehl für Arepas."}], "image_alt": "Mais-Arepas mit Käse", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}, {"id": "f8d50b95-6a10-5996-9432-6d9fe4bc8663", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "en", "slug": "sweet-corn-arepas-with-cheese", "public_path": "/en/sweet-corn-arepas-with-cheese", "source_url": null, "title": "Sweet corn arepas with cheese", "excerpt": "Colombian sweet corn arepas, cooked in a skillet and topped with mozzarella. Makes four, with a thick batter, resting time and two cooking batches.", "summary": "Colombian sweet corn arepas, cooked in a skillet and topped with mozzarella. Makes four, with a thick batter, resting time and two cooking batches.", "content_html": "<p>Colombian sweet corn arepas, cooked in a skillet and topped with mozzarella. Makes four, with a thick batter, resting time and two cooking batches.</p>", "category": "Breads & doughs", "category_slug": "panes-y-masas", "cuisine": "Colombian", "difficulty": "Easy", "course": "Breads & doughs", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "raw fresh sweet corn kernels", "group": "Batter"}, {"amount": "60", "unit": "g", "name": "yellow precooked maize flour for arepas", "group": "Batter"}, {"amount": "40", "unit": "g", "name": "whole milk", "group": "Batter"}, {"amount": "20", "unit": "g", "name": "unsalted butter: 10 g for the batter and 10 g for the pan", "group": "Batter and cooking"}, {"amount": "12", "unit": "g", "name": "white sugar", "group": "Batter"}, {"amount": "2", "unit": "g", "name": "fine salt", "group": "Batter"}, {"amount": "120", "unit": "g", "name": "whole-milk mozzarella, sliced", "group": "Topping"}], "steps": [{"title": "Process the corn", "content": "Remove silks and pieces of cob and weigh 500 g of edible kernels. Pulse with 40 g milk, the sugar and salt until you have a coarse paste with small corn pieces. Do not add water or blend into a thin liquid. Melt 10 g butter and let it cool slightly.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "Fresh sweet corn coarsely processed with milk"}, {"title": "Mix and rest", "content": "Transfer the corn to a bowl. Stir in 60 g precooked maize flour and 10 g melted butter. Rest for 10 minutes. The batter should be thick, falling slowly from a spoon, and spreadable rather than firm enough to knead. If too runny, wait another 5 minutes; extra flour or liquid changes the formula and estimated nutrition.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "Thick yellow corn batter lifted with a spoon"}, {"title": "Shape and cook the first side", "content": "Heat a large nonstick skillet over medium-low heat for 3 minutes. Use 5 g of the remaining butter for the first batch. Divide the batter into four equal portions, cooking two at a time. Spread each into a circle about 12 cm wide and 1 cm thick. Cook undisturbed for 5 minutes, until the edge is set and the underside golden. Reduce the heat if it browns before the edge firms up.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "Two sweet corn arepas cooking on their first side"}, {"title": "Turn and melt the cheese", "content": "Slide a wide spatula underneath and turn carefully. Cook the second side for 5 minutes. Put 30 g mozzarella on each arepa, cover and heat for 1 more minute until softened. The center must be set, with no raw paste; if still raw and wet, cook longer over low heat. Repeat with the remaining batter and last 5 g butter.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "Golden arepas in a skillet topped with melting mozzarella"}, {"title": "Serve warm", "content": "Serve one unfolded arepa with 30 g cheese per person. The approximate time includes 10 minutes preparation, 10 minutes resting and 25 minutes cooking in two batches; add any extra time your skillet needs. Cool leftovers and refrigerate within 2 hours at 4 °C or below. Eat within 3 days and reheat until hot throughout.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "Four golden sweet corn arepas with mozzarella on a plate"}], "notes": "Original editorial proposal, not yet kitchen-tested. Contains milk. Use raw fresh sweet corn; thaw and drain frozen corn before weighing. Canned corn and other flours require moisture adjustments. Use precooked arepa flour, not coarse polenta. Sweetness varies with the corn. Fresh Colombian cheese can replace mozzarella but texture and nutrition will change. Estimated nutrition includes all 20 g butter; pan residue has not been measured. Side dishes are excluded.", "keywords": ["Sweet corn arepas with cheese"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "One of 4 arepas with 30 g cheese", "method": "Sum edible ingredient grams × USDA nutrients per 100 g, divided by 4. Includes all 20 g butter; cooked yield and pan residue are not measured.", "note": "Estimate, not a laboratory analysis or kitchen test. Generic yellow corn flour is a nutrition proxy for precooked arepa flour; brands differ. Includes all butter and cheese, without side dishes."}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "Sweet corn arepas with cheese"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "Sweet corn arepas with cheese", "description": "Colombian sweet corn arepas, cooked in a skillet and topped with mozzarella. Makes four, with a thick batter, resting time and two cooking batches.", "about": "Colombian sweet corn arepas, cooked in a skillet and topped with mozzarella. Makes four, with a thick batter, resting time and two cooking batches.", "faq": [{"q": "Why does it break when turned?", "a": "It may need more resting or first-side cooking time. Wait until the edge sets and use a wide spatula; do not turn while the base is still sticking."}, {"q": "Can I use frozen corn?", "a": "Yes, thaw and drain it well, then weigh 500 g. Moisture varies; rest the batter and check that it is thick before cooking."}, {"q": "Can I replace the flour with polenta?", "a": "Not directly: coarse polenta hydrates differently. This formula uses precooked maize flour for arepas."}], "image_alt": "Sweet corn arepas with cheese", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}, {"id": "4d294bdd-c777-57a1-ada0-6d9225319e8a", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "fr", "slug": "arepas-de-mais-au-fromage", "public_path": "/fr/arepas-de-mais-au-fromage", "source_url": null, "title": "Arepas de maïs au fromage", "excerpt": "Arepas colombiennes au maïs doux, dorées à la poêle et garnies de mozzarella. Quatre pièces, avec une pâte épaisse, un repos et deux fournées.", "summary": "Arepas colombiennes au maïs doux, dorées à la poêle et garnies de mozzarella. Quatre pièces, avec une pâte épaisse, un repos et deux fournées.", "content_html": "<p>Arepas colombiennes au maïs doux, dorées à la poêle et garnies de mozzarella. Quatre pièces, avec une pâte épaisse, un repos et deux fournées.</p>", "category": "Pains et pâtes", "category_slug": "panes-y-masas", "cuisine": "Colombienne", "difficulty": "Facile", "course": "Pains et pâtes", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "grains de maïs doux frais et crus", "group": "Pâte"}, {"amount": "60", "unit": "g", "name": "farine de maïs jaune précuite pour arepas", "group": "Pâte"}, {"amount": "40", "unit": "g", "name": "lait entier", "group": "Pâte"}, {"amount": "20", "unit": "g", "name": "beurre doux : 10 g pour la pâte et 10 g pour la poêle", "group": "Pâte et cuisson"}, {"amount": "12", "unit": "g", "name": "sucre blanc", "group": "Pâte"}, {"amount": "2", "unit": "g", "name": "sel fin", "group": "Pâte"}, {"amount": "120", "unit": "g", "name": "mozzarella au lait entier, en tranches", "group": "Garniture"}], "steps": [{"title": "Mixer le maïs", "content": "Retirez les filaments et débris d'épi, puis pesez 500 g de grains comestibles. Mixez par brèves impulsions avec 40 g de lait, le sucre et le sel, pour obtenir une pâte grossière avec de petits morceaux. N'ajoutez pas d'eau et ne réduisez pas en liquide. Faites fondre 10 g de beurre et laissez tiédir.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "Maïs doux grossièrement mixé avec du lait"}, {"title": "Mélanger et laisser reposer", "content": "Versez dans un bol. Incorporez 60 g de farine de maïs précuite et 10 g de beurre fondu. Laissez reposer 10 minutes. La pâte épaisse doit tomber lentement de la cuillère et pouvoir s'étaler, sans être ferme à pétrir. Si elle est trop liquide, attendez encore 5 minutes ; tout ajout de farine ou liquide modifie la formule et les valeurs estimées.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "Pâte de maïs jaune épaisse sur une cuillère"}, {"title": "Former et dorer la première face", "content": "Chauffez une grande poêle antiadhésive à feu moyen-doux pendant 3 minutes. Utilisez 5 g du beurre restant pour la première fournée. Divisez la pâte en quatre parts égales et cuisez-en deux à la fois. Étalez chaque part en cercle d'environ 12 cm et de 1 cm d'épaisseur. Cuisez 5 minutes sans déplacer, jusqu'à ce que le bord soit ferme et le dessous doré. Baissez le feu si la coloration est trop rapide.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "Deux arepas de maïs cuisant sur leur première face"}, {"title": "Retourner et faire fondre le fromage", "content": "Glissez une spatule large dessous et retournez délicatement. Cuisez l'autre face 5 minutes. Posez 30 g de mozzarella sur chaque arepa, couvrez et chauffez encore 1 minute. Le centre doit être pris, sans pâte crue ; sinon, prolongez à feu doux. Recommencez avec le reste de pâte et les derniers 5 g de beurre.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "Arepas dorées et mozzarella fondante dans la poêle"}, {"title": "Servir chaud", "content": "Servez une arepa non pliée avec 30 g de fromage par personne. Le temps indicatif comprend 10 minutes de préparation, 10 de repos et 25 de cuisson en deux fournées ; adaptez à la poêle. Refroidissez les restes et réfrigérez-les sous 2 heures à 4 °C maximum. Consommez sous 3 jours et réchauffez jusqu'à ce que le centre soit bien chaud.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "Quatre arepas dorées au maïs et à la mozzarella"}], "notes": "Proposition éditoriale originale, non testée en cuisine. Contient du lait. Utilisez du maïs doux frais cru ; décongelez et égouttez le maïs surgelé avant pesée. Le maïs en conserve et les autres farines demandent un ajustement de l'humidité. Utilisez une farine précuite pour arepas, pas une polenta grossière. La douceur varie selon le maïs. Un fromage frais colombien est possible, avec une texture et des valeurs différentes. L'estimation inclut les 20 g de beurre ; les résidus dans la poêle ne sont pas mesurés. Sans accompagnements.", "keywords": ["Arepas de maïs au fromage"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "Une des 4 arepas avec 30 g de fromage", "method": "Somme des grammes comestibles × valeurs USDA pour 100 g, divisée par 4. Les 20 g de beurre sont inclus ; rendement cuit et résidus non mesurés.", "note": "Estimation, sans analyse de laboratoire ni essai en cuisine. La farine de maïs jaune générique sert de référence approximative pour la farine précuite ; les marques varient. Beurre et fromage inclus, sans accompagnements."}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "Arepas de maïs au fromage"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "Arepas de maïs au fromage", "description": "Arepas colombiennes au maïs doux, dorées à la poêle et garnies de mozzarella. Quatre pièces, avec une pâte épaisse, un repos et deux fournées.", "about": "Arepas colombiennes au maïs doux, dorées à la poêle et garnies de mozzarella. Quatre pièces, avec une pâte épaisse, un repos et deux fournées.", "faq": [{"q": "Pourquoi l'arepa se casse-t-elle en la retournant ?", "a": "Elle manque peut-être de repos ou de cuisson sur la première face. Attendez que le bord soit ferme et utilisez une spatule large ; ne retournez pas tant que le dessous colle."}, {"q": "Puis-je utiliser du maïs surgelé ?", "a": "Oui, décongelé et bien égoutté, en pesant 500 g. L'humidité varie : laissez reposer et vérifiez que la pâte est épaisse avant cuisson."}, {"q": "Puis-je remplacer la farine par de la polenta ?", "a": "Pas directement : la polenta grossière s'hydrate différemment. Cette formule utilise une farine de maïs précuite pour arepas."}], "image_alt": "Arepas de maïs au fromage", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}, {"id": "d101897d-4437-550d-b782-9ec9e69a2be3", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "it", "slug": "arepas-di-mais-con-formaggio", "public_path": "/it/arepas-di-mais-con-formaggio", "source_url": null, "title": "Arepas di mais con formaggio", "excerpt": "Arepas colombiane di mais dolce, dorate in padella e coperte di mozzarella. Quattro pezzi con impasto denso, riposo e cottura in due turni.", "summary": "Arepas colombiane di mais dolce, dorate in padella e coperte di mozzarella. Quattro pezzi con impasto denso, riposo e cottura in due turni.", "content_html": "<p>Arepas colombiane di mais dolce, dorate in padella e coperte di mozzarella. Quattro pezzi con impasto denso, riposo e cottura in due turni.</p>", "category": "Pane e impasti", "category_slug": "panes-y-masas", "cuisine": "Colombiana", "difficulty": "Facile", "course": "Pane e impasti", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "chicchi di mais dolce fresco crudo", "group": "Impasto"}, {"amount": "60", "unit": "g", "name": "farina di mais gialla precotta per arepas", "group": "Impasto"}, {"amount": "40", "unit": "g", "name": "latte intero", "group": "Impasto"}, {"amount": "20", "unit": "g", "name": "burro non salato: 10 g per l'impasto e 10 g per la padella", "group": "Impasto e cottura"}, {"amount": "12", "unit": "g", "name": "zucchero bianco", "group": "Impasto"}, {"amount": "2", "unit": "g", "name": "sale fino", "group": "Impasto"}, {"amount": "120", "unit": "g", "name": "mozzarella di latte intero, a fette", "group": "Copertura"}], "steps": [{"title": "Frulla il mais", "content": "Elimina filamenti e residui del tutolo e pesa 500 g di chicchi commestibili. Frulla a impulsi brevi con 40 g di latte, zucchero e sale, ottenendo una pasta grossolana con piccoli pezzi di mais. Non aggiungere acqua e non renderla liquida. Sciogli 10 g di burro e lascia intiepidire.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "Mais dolce tritato grossolanamente con latte"}, {"title": "Mescola e lascia riposare", "content": "Trasferisci il mais in una ciotola. Incorpora 60 g di farina di mais precotta e 10 g di burro fuso. Riposa 10 minuti. L'impasto deve essere denso, cadere lentamente dal cucchiaio e potersi stendere, senza essere sodo da impastare. Se troppo liquido, aspetta altri 5 minuti; aggiunte di farina o liquido modificano formula e valori stimati.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "Impasto denso di mais giallo sollevato con un cucchiaio"}, {"title": "Forma e dora il primo lato", "content": "Scalda una grande padella antiaderente a fuoco medio-basso per 3 minuti. Usa 5 g del burro rimanente per il primo turno. Dividi l'impasto in quattro parti uguali e cuocine due alla volta. Stendi ciascuna in un disco di circa 12 cm, spesso 1 cm. Cuoci senza muovere per 5 minuti, finché il bordo è fermo e la base dorata. Abbassa il fuoco se prende colore troppo presto.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "Due arepas di mais in cottura sul primo lato"}, {"title": "Gira e sciogli il formaggio", "content": "Inserisci una spatola larga sotto e gira delicatamente. Cuoci il secondo lato 5 minuti. Metti 30 g di mozzarella su ciascuna arepa, copri e scalda ancora 1 minuto. Il centro deve essere rappreso, senza pasta cruda; altrimenti prolunga a fuoco basso. Ripeti con l'impasto restante e gli ultimi 5 g di burro.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "Arepas dorate con mozzarella che fonde in padella"}, {"title": "Servi calde", "content": "Servi un'arepa non piegata con 30 g di formaggio a persona. Il tempo indicativo comprende 10 minuti di preparazione, 10 di riposo e 25 di cottura in due turni; aggiungi il tempo necessario per la tua padella. Raffredda gli avanzi e mettili in frigorifero entro 2 ore, a 4 °C o meno. Consumali entro 3 giorni e riscaldali finché sono ben caldi al centro.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "Quattro arepas dorate di mais con mozzarella sul piatto"}], "notes": "Proposta editoriale originale, non ancora provata in cucina. Contiene latte. Usa mais dolce fresco crudo; scongela e scola quello congelato prima di pesarlo. Mais in scatola e altre farine richiedono correzioni dell'umidità. Usa farina precotta per arepas, non polenta grossa. La dolcezza varia con il mais. Il formaggio fresco colombiano è possibile, ma cambia consistenza e nutrienti. La stima include tutti i 20 g di burro; i residui in padella non sono misurati. Contorni esclusi.", "keywords": ["Arepas di mais con formaggio"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "Una delle 4 arepas con 30 g di formaggio", "method": "Somma dei grammi commestibili × nutrienti USDA per 100 g, divisa per 4. Include tutti i 20 g di burro; resa cotta e residui non misurati.", "note": "Stima, non analisi di laboratorio né prova in cucina. La farina di mais gialla generica è un riferimento approssimativo per quella precotta; le marche variano. Include burro e formaggio, senza contorni."}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "Arepas di mais con formaggio"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "Arepas di mais con formaggio", "description": "Arepas colombiane di mais dolce, dorate in padella e coperte di mozzarella. Quattro pezzi con impasto denso, riposo e cottura in due turni.", "about": "Arepas colombiane di mais dolce, dorate in padella e coperte di mozzarella. Quattro pezzi con impasto denso, riposo e cottura in due turni.", "faq": [{"q": "Perché si rompe quando la giro?", "a": "Può mancare riposo o cottura del primo lato. Aspetta un bordo fermo e usa una spatola larga; non girare finché la base resta attaccata."}, {"q": "Posso usare mais congelato?", "a": "Sì, scongelato e ben scolato, pesandone 500 g. L'umidità varia: lascia riposare e controlla che l'impasto sia denso prima di cuocerlo."}, {"q": "Posso usare polenta al posto della farina?", "a": "Non direttamente: la polenta grossa si idrata diversamente. La formula usa farina di mais precotta per arepas."}], "image_alt": "Arepas di mais con formaggio", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}, {"id": "efdf2644-c1f4-515d-a85b-2b3e5ba11e05", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "ja", "slug": "スイートコーンとチーズのアレパ", "public_path": "/ja/スイートコーンとチーズのアレパ", "source_url": null, "title": "スイートコーンとチーズのアレパ", "excerpt": "生のスイートコーンで作るコロンビアのアレパ。フライパンで香ばしく焼き、モッツァレラをのせます。生地を休ませ、2回に分けて4枚を焼きます。", "summary": "生のスイートコーンで作るコロンビアのアレパ。フライパンで香ばしく焼き、モッツァレラをのせます。生地を休ませ、2回に分けて4枚を焼きます。", "content_html": "<p>生のスイートコーンで作るコロンビアのアレパ。フライパンで香ばしく焼き、モッツァレラをのせます。生地を休ませ、2回に分けて4枚を焼きます。</p>", "category": "パン・生地料理", "category_slug": "panes-y-masas", "cuisine": "コロンビア料理", "difficulty": "簡単", "course": "パン・生地料理", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "生のスイートコーンの粒", "group": "生地"}, {"amount": "60", "unit": "g", "name": "アレパ用の加熱済み黄色とうもろこし粉", "group": "生地"}, {"amount": "40", "unit": "g", "name": "全乳", "group": "生地"}, {"amount": "20", "unit": "g", "name": "無塩バター：生地用10 g、フライパン用10 g", "group": "生地と焼き用"}, {"amount": "12", "unit": "g", "name": "白砂糖", "group": "生地"}, {"amount": "2", "unit": "g", "name": "細粒塩", "group": "生地"}, {"amount": "120", "unit": "g", "name": "全乳のモッツァレラ（薄切り）", "group": "トッピング"}], "steps": [{"title": "とうもろこしを粗く砕く", "content": "ひげや芯のかけらを取り除き、食べられる粒500 gを量ります。牛乳40 g、砂糖、塩と一緒に短いパルスで粗く砕き、小さな粒が残るペーストにします。水を加えたり、さらさらの液体になるまで混ぜたりしないでください。バター10 gを溶かし、少し冷まします。", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "牛乳と一緒に粗く砕いたスイートコーン"}, {"title": "混ぜて休ませる", "content": "とうもろこしをボウルに移し、加熱済みとうもろこし粉60 gと溶かしたバター10 gを混ぜ、10分休ませます。スプーンからゆっくり落ち、広げられる濃い生地にします。手でこねる固さではありません。水っぽければさらに5分待ちます。粉や液体を追加すると配合と推定栄養値が変わります。", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "スプーンで持ち上げた濃い黄色のとうもろこし生地"}, {"title": "形を整えて片面を焼く", "content": "大きな焦げつきにくいフライパンを弱めの中火で3分温めます。残りのバターのうち5 gを最初の2枚に使います。生地を4等分し、2枚ずつ焼きます。各部分を直径約12 cm、厚さ1 cmに広げ、動かさず5分焼きます。縁が固まり、底がきつね色になれば目安です。縁が固まる前に焦げそうなら火を弱めます。", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "フライパンで片面を焼いている2枚のアレパ"}, {"title": "裏返してチーズを溶かす", "content": "幅広のフライ返しを下に差し込み、そっと裏返します。反対側を5分焼き、1枚にモッツァレラ30 gをのせます。ふたをしてさらに1分加熱し、チーズを柔らかくします。中心に生のペーストが残らないようにし、まだ生なら弱火で追加加熱します。残りの生地と最後のバター5 gでも同様に焼きます。", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "焼き色のついたアレパと溶けるモッツァレラ"}, {"title": "温かいうちに盛り付ける", "content": "折りたたまず、1人分としてチーズ30 gをのせたアレパ1枚を出します。目安は準備10分、休ませる時間10分、2回分の加熱25分です。フライパンに応じて追加時間を取ってください。残りは冷まし、2時間以内に4 °C以下で冷蔵します。3日以内に食べ、中心まで十分熱くなるよう再加熱します。", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "皿に盛り付けたチーズ付きのアレパ4枚"}], "notes": "独自の編集レシピ案で、調理試験は未実施です。乳を含みます。生の新鮮なスイートコーンを使い、冷凍品は解凍して水を切ってから量ります。缶詰や別の粉では水分調整が必要です。粗いポレンタではなくアレパ用の加熱済み粉を使います。甘さはとうもろこしによって変わります。コロンビアのフレッシュチーズにも替えられますが、食感と栄養値は変わります。推定値にはバター20 g全量を含み、フライパンに残る量は測定していません。付け合わせは含みません。", "keywords": ["スイートコーンとチーズのアレパ"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "4枚のうち1枚、チーズ30 g付き", "method": "食べられる材料の重量とUSDAの100 g当たり栄養値を掛けて合計し、4で割りました。バター20 g全量を含み、焼き上がり重量とフライパンの残量は未測定です。", "note": "推定値で、検査や調理試験の結果ではありません。黄色とうもろこし粉の一般的なデータを加熱済みアレパ粉の近似値として使いました。製品によって異なります。バターとチーズを含み、付け合わせは含みません。"}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "スイートコーンとチーズのアレパ"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "スイートコーンとチーズのアレパ", "description": "生のスイートコーンで作るコロンビアのアレパ。フライパンで香ばしく焼き、モッツァレラをのせます。生地を休ませ、2回に分けて4枚を焼きます。", "about": "生のスイートコーンで作るコロンビアのアレパ。フライパンで香ばしく焼き、モッツァレラをのせます。生地を休ませ、2回に分けて4枚を焼きます。", "faq": [{"q": "裏返すと割れるのはなぜですか？", "a": "休ませる時間や片面の加熱が不足している可能性があります。縁が固まるまで待ち、幅広のフライ返しを使います。底がくっついている間は返さないでください。"}, {"q": "冷凍とうもろこしは使えますか？", "a": "はい。解凍し、よく水を切って500 gを量ります。水分が異なるので生地を休ませ、焼く前に濃い状態になっていることを確認します。"}, {"q": "粉をポレンタに替えられますか？", "a": "同量の置き換えはできません。粗いポレンタは水の吸収が異なります。この配合はアレパ用の加熱済みとうもろこし粉を使います。"}], "image_alt": "スイートコーンとチーズのアレパ", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}, {"id": "86a75108-3762-553a-8d04-9269fafff8f2", "recipe_group_id": "5e854cea-0e2b-4d79-be8b-6fcd6fa374a9", "language": "pt", "slug": "arepas-de-milho-verde-com-queijo", "public_path": "/pt/arepas-de-milho-verde-com-queijo", "source_url": null, "title": "Arepas de milho verde com queijo", "excerpt": "Arepas colombianas de milho verde, douradas na frigideira e cobertas com muçarela. Quatro unidades com massa espessa, descanso e preparo em duas levas.", "summary": "Arepas colombianas de milho verde, douradas na frigideira e cobertas com muçarela. Quatro unidades com massa espessa, descanso e preparo em duas levas.", "content_html": "<p>Arepas colombianas de milho verde, douradas na frigideira e cobertas com muçarela. Quatro unidades com massa espessa, descanso e preparo em duas levas.</p>", "category": "Pães e massas", "category_slug": "panes-y-masas", "cuisine": "Colombiana", "difficulty": "Fácil", "course": "Pães e massas", "servings": 4, "prep_time_minutes": 10, "cook_time_minutes": 25, "total_time_minutes": 45, "ingredients": [{"amount": "500", "unit": "g", "name": "grãos de milho verde fresco, crus", "group": "Massa"}, {"amount": "60", "unit": "g", "name": "farinha de milho amarela pré-cozida própria para arepas", "group": "Massa"}, {"amount": "40", "unit": "g", "name": "leite integral", "group": "Massa"}, {"amount": "20", "unit": "g", "name": "manteiga sem sal: 10 g para a massa e 10 g para a frigideira", "group": "Massa e preparo na frigideira"}, {"amount": "12", "unit": "g", "name": "açúcar branco", "group": "Massa"}, {"amount": "2", "unit": "g", "name": "sal fino", "group": "Massa"}, {"amount": "120", "unit": "g", "name": "muçarela de leite integral, fatiada", "group": "Cobertura"}], "steps": [{"title": "Triture o milho", "content": "Retire os fios e restos de sabugo e pese 500 g de grãos comestíveis. Triture em pulsos curtos com 40 g de leite, açúcar e sal, até obter uma pasta com pequenos pedaços de milho. Não acrescente água nem bata até virar um líquido fino. Derreta 10 g de manteiga e deixe amornar.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-01.webp", "image_alt": "Milho verde triturado com leite no processador"}, {"title": "Misture e deixe descansar", "content": "Transfira o milho para uma tigela. Incorpore 60 g de farinha de milho pré-cozida e 10 g de manteiga derretida. Descanse por 10 minutos. A massa deve ficar espessa, cair lentamente da colher e poder ser espalhada, sem ficar firme para sovar. Se estiver líquida demais, aguarde mais 5 minutos; farinha ou líquido extras alteram a fórmula e a nutrição estimada.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-02.webp", "image_alt": "Massa espessa de milho amarelo levantada com uma colher"}, {"title": "Modele e doure o primeiro lado", "content": "Aqueça uma frigideira antiaderente grande em fogo médio-baixo por 3 minutos. Use 5 g da manteiga restante na primeira leva. Divida a massa em quatro partes iguais e prepare duas por vez. Espalhe cada porção em um círculo de cerca de 12 cm e 1 cm de espessura. Cozinhe sem mexer por 5 minutos, até a borda firmar e a base dourar. Abaixe o fogo se dourar antes de firmar.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-03.webp", "image_alt": "Duas arepas de milho verde cozinhando pelo primeiro lado"}, {"title": "Vire e derreta o queijo", "content": "Passe uma espátula larga por baixo e vire com cuidado. Cozinhe o segundo lado por 5 minutos. Coloque 30 g de muçarela sobre cada arepa, tampe e aqueça por mais 1 minuto. O centro deve estar firme, sem massa crua; se continuar cru e úmido, prolongue em fogo baixo. Repita com o restante da massa e os últimos 5 g de manteiga.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-04.webp", "image_alt": "Arepas douradas na frigideira com muçarela derretendo"}, {"title": "Sirva quentes", "content": "Sirva uma arepa sem dobrar com 30 g de queijo por pessoa. O tempo aproximado soma 10 minutos de preparo, 10 de descanso e 25 na frigideira em duas levas; acrescente o tempo extra necessário. Esfrie as sobras e leve à geladeira em até 2 horas, a 4 °C ou menos. Consuma em 3 dias e reaqueça até o centro ficar bem quente.", "image_url": "/recetas/arepas-de-choclo-con-queso/paso-05.webp", "image_alt": "Quatro arepas douradas de milho verde com muçarela no prato"}], "notes": "Proposta editorial original, ainda não testada na cozinha. Contém leite. Use milho verde fresco cru; descongele e escorra o congelado antes de pesar. Milho em conserva e outras farinhas exigem ajuste da umidade. Use farinha pré-cozida para arepas, não polenta grossa. A doçura depende do milho. Queijo fresco colombiano pode substituir a muçarela, mas textura e nutrientes mudam. A estimativa inclui todos os 20 g de manteiga; resíduos na frigideira não foram medidos. Não inclui acompanhamentos.", "keywords": ["Arepas de milho verde com queijo"], "nutrition": {"calories": 307.0, "protein_g": 11.9, "carbs_g": 40.0, "fat_g": 12.9, "saturated_fat_g": 7.3, "fiber_g": 2.8, "sugar_g": 11.4, "sodium_mg": 363.6, "estimated": true, "source": "USDA FoodData Central — SR Legacy (2018)", "source_url": "https://fdc.nal.usda.gov/", "inputs": [{"fdc_id": 169998, "description": "Corn, sweet, yellow, raw", "recipe_grams": 500, "edible_grams": 500, "per_100g": {"fiber_g": 2.0, "sodium_mg": 15.0, "protein_g": 3.27, "fat_g": 1.35, "sugar_g": 6.26, "saturated_fat_g": 0.325, "carbs_g": 18.7, "calories": 86.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169998/nutrients"}, {"fdc_id": 169695, "description": "Corn flour, yellow, degermed, unenriched", "recipe_grams": 60, "edible_grams": 60, "per_100g": {"saturated_fat_g": 0.171, "sugar_g": 0.64, "fat_g": 1.39, "carbs_g": 82.8, "calories": 375, "protein_g": 5.59, "fiber_g": 1.9, "sodium_mg": 1.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169695/nutrients"}, {"fdc_id": 171265, "description": "Milk, whole, 3.25% milkfat, with added vitamin D", "recipe_grams": 40, "edible_grams": 40, "per_100g": {"fat_g": 3.25, "sugar_g": 5.05, "carbs_g": 4.8, "calories": 61.0, "saturated_fat_g": 1.86, "fiber_g": 0.0, "sodium_mg": 43.0, "protein_g": 3.15}, "source_url": "https://fdc.nal.usda.gov/food-details/171265/nutrients"}, {"fdc_id": 173430, "description": "Butter, without salt", "recipe_grams": 20, "edible_grams": 20, "per_100g": {"sugar_g": 0.06, "calories": 717, "saturated_fat_g": 50.5, "fat_g": 81.1, "carbs_g": 0.06, "protein_g": 0.85, "fiber_g": 0.0, "sodium_mg": 11.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173430/nutrients"}, {"fdc_id": 169655, "description": "Sugars, granulated", "recipe_grams": 12, "edible_grams": 12, "per_100g": {"protein_g": 0.0, "sodium_mg": 1.0, "fat_g": 0.0, "calories": 387, "saturated_fat_g": 0.0, "sugar_g": 99.8, "carbs_g": 100, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/169655/nutrients"}, {"fdc_id": 173468, "description": "Salt, table", "recipe_grams": 2, "edible_grams": 2, "per_100g": {"fiber_g": 0.0, "sodium_mg": 38800.0, "saturated_fat_g": 0.0, "protein_g": 0.0, "fat_g": 0.0, "carbs_g": 0.0, "calories": 0.0, "sugar_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/173468/nutrients"}, {"fdc_id": 170845, "description": "Cheese, mozzarella, whole milk", "recipe_grams": 120, "edible_grams": 120, "per_100g": {"protein_g": 22.2, "sodium_mg": 486, "saturated_fat_g": 13.9, "sugar_g": 0.0, "fat_g": 22.1, "carbs_g": 2.4, "calories": 299, "fiber_g": 0.0}, "source_url": "https://fdc.nal.usda.gov/food-details/170845/nutrients"}], "serving_size": "Uma das 4 arepas com 30 g de queijo", "method": "Soma dos gramas comestíveis × nutrientes USDA por 100 g, dividida por 4. Inclui todos os 20 g de manteiga; rendimento cozido e resíduos não foram medidos.", "note": "Estimativa, sem análise de laboratório nem teste na cozinha. Farinha de milho amarela genérica é uma aproximação nutricional da farinha pré-cozida; marcas variam. Inclui manteiga e queijo, sem acompanhamentos."}, "image_url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "gallery": [{"url": "/recetas/arepas-de-choclo-con-queso/portada.webp", "alt": "Arepas de milho verde com queijo"}], "video_urls": [], "published": true, "editorial_status": "published", "seo": {"title": "Arepas de milho verde com queijo", "description": "Arepas colombianas de milho verde, douradas na frigideira e cobertas com muçarela. Quatro unidades com massa espessa, descanso e preparo em duas levas.", "about": "Arepas colombianas de milho verde, douradas na frigideira e cobertas com muçarela. Quatro unidades com massa espessa, descanso e preparo em duas levas.", "faq": [{"q": "Por que quebra ao virar?", "a": "Pode faltar descanso ou cozimento do primeiro lado. Espere a borda firmar e use uma espátula larga; não vire enquanto a base ainda estiver grudada."}, {"q": "Posso usar milho congelado?", "a": "Sim, descongelado e bem escorrido, pesando 500 g. A umidade varia; descanse a mistura e confira se está espessa antes de cozinhar."}, {"q": "Posso substituir a farinha por polenta?", "a": "Não diretamente: a polenta grossa hidrata de outro jeito. Esta fórmula usa farinha de milho pré-cozida própria para arepas."}], "image_alt": "Arepas de milho verde com queijo", "image_variants": ["/recetas/arepas-de-choclo-con-queso/portada-1x1.webp", "/recetas/arepas-de-choclo-con-queso/portada-4x3.webp", "/recetas/arepas-de-choclo-con-queso/portada-16x9.webp"]}}]$records$; outside_hash text; n int;
BEGIN
IF (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>159 THEN RAISE EXCEPTION 'Catalog changed: reconcile baseline'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_populate_recordset(NULL::public.recipes,j)x ON r.id=x.id OR r.recipe_group_id=x.recipe_group_id OR r.public_path=x.public_path OR (r.language=x.language AND r.slug=x.slug)) OR EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_populate_recordset(NULL::public.recipes,j)x ON p.public_path=x.public_path OR (p.language=x.language AND p.slug=x.slug)) THEN RAISE EXCEPTION 'Identity, slug or path collision'; END IF;
SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) INTO outside_hash FROM public.recipes r;
INSERT INTO public.recipes(id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published,published_at) SELECT x.id,x.recipe_group_id,x.language,x.slug,x.public_path,x.source_url,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,x.content_html,x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',now(),true,now() FROM jsonb_populate_recordset(NULL::public.recipes,j)x;
GET DIAGNOSTICS n=ROW_COUNT;
IF n<>7 OR (SELECT count(DISTINCT language) FROM public.recipes WHERE recipe_group_id='5e854cea-0e2b-4d79-be8b-6fcd6fa374a9')<>7 THEN RAISE EXCEPTION 'New group is not complete7/7'; END IF;
IF (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>160 THEN RAISE EXCEPTION 'Unexpected final catalog'; END IF;
IF outside_hash IS DISTINCT FROM (SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) FROM public.recipes r WHERE recipe_group_id<>'5e854cea-0e2b-4d79-be8b-6fcd6fa374a9') THEN RAISE EXCEPTION 'Unrelated recipe changed'; END IF;
END $publish$;
COMMIT;
